package com.bank.recon;

import java.util.logging.Logger;

public class ReconciliationSplitter {

    private static final Logger log = Logger.getLogger(ReconciliationSplitter.class.getName());

    public boolean canPartition(int[] amounts) {
        int total = 0;
        for (int a : amounts) total += a;
        if (total % 2 != 0) {                          // odd total ⇒ impossible
            log.warning("Total is odd; cannot split equally");
            return false;
        }
        int target = total / 2;
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;                                  // sum 0 reachable by taking nothing
        for (int num : amounts) {
            for (int s = target; s >= num; s--) {      // DOWNWARD ⇒ each number once
                dp[s] = dp[s] || dp[s - num];
            }
        }
        boolean result = dp[target];
        log.info(() -> "Equal partition possible = " + result);
        return result;
    }
}
