package com.bank.recon;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class PartitionDemo {

    private static final Logger log = Logger.getLogger(PartitionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Reconciliation Splitter (Partition Equal Subset)");
        ReconciliationSplitter splitter = new ReconciliationSplitter();
        log.info("{1,5,11,5} → " + splitter.canPartition(new int[]{1, 5, 11, 5})); // true
        log.info("{1,2,3,5} → " + splitter.canPartition(new int[]{1, 2, 3, 5}));   // false
    }
}
